  "karte.gruppen.voll": "Группы сформированы в полном векторном пространстве — не на карте, которая из-за плоского экрана лишь приближённая проекция с потерями. ",
  "karte.gruppen.geschichten": "Названия групп — это слова-места: слова из твоих собственных песен, живущие там, где находится группа; группа без чёткого места называется «(смешанная страна)». ",
