  "player.karaoke.fehlt": "Караоке — нет временных меток. В «Обновить коллекцию» шаг «Временные якоря караоке с Whisper» создаёт их для треков с текстом песни.",
  "player.lyrics.fehlt": "Текст песни — не сохранён. Для треков с вокалом закладка «KlangTresor morgens» в Suno подгружает текст песни.",
  "player.analyse.fehlt": "Анализ трека — нет в архиве. Если трек из твоего архива, «Обновить коллекцию» (шаг «Анализ треков») его рассчитает; чужие треки не анализируются.",
