  "morgen.abgebrochen": "Прервано – причину смотри в «Подробностях» красного шага и снова нажми «Обновить коллекцию»; готовая работа сохранена.",
  "morgen.durch_fehler": "Готово — {n} шаг с ошибкой. Открой его «Подробности» и запусти снова.|Готово — {n} шага с ошибками. Открой их «Подробности» и запусти снова.|Готово — {n} шагов с ошибками. Открой их «Подробности» и запусти снова.",
