  "morgen.kreuz.ernte": "Подмешать данные закладки",
  "morgen.kreuz.ernte.text": "Профиль, приватные треки, подписчики и история счётчиков — подмешиваются при сборке каталога.",
  "morgen.kreuz.kommentare": "Сохранить комментарии",
