  "morgen.kreuz.medien": "Загрузить медиа",
  "morgen.kreuz.medien.text": "Недостающие MP3, обложки, видео — и WAV, уже созданные на Suno. Расходует сеть и место на диске.",
  "morgen.kreuz.nachbarn": "Обновить окружение",
  "morgen.kreuz.nachbarn.text": "Публичные показатели профилей и h-индекс тех, кто появился со вчерашнего дня — обычно секунды. Полное обновление остаётся кнопкой на панели окружения.",
  "morgen.kreuz.katalog": "Собрать каталог",
