  "morgen.kreuz.analyse.text": "BPM, тональность, громкость, частотный профиль, гистограмма, поисковый индекс.",
  "morgen.kreuz.whisper": "Временные метки для караоке через Whisper",
  "morgen.kreuz.whisper.text": "Сначала новые треки только с текстом песни, затем выравнивание текста. Около 3 мин на трек; Mac не засыпает.",
  "morgen.kreuz.musikstil": "Музыкальный стиль и карта музыки",
