  "profil.nb.y": "Сколько у него подписчиков?",
  "profil.nb.essay": "По горизонтали — на кого подписан человек, по вертикали — кто подписан на него. Обе оси логарифмические. На линии обе стороны уравновешены. Ниже: охват за счёт взаимности (r = {r}). Выше: на человека подписано больше людей, чем он сам подписан — {oben} из {n}. Клик по точке открывает профиль на Suno.",
