  "profil.nb.saeulen": "Каждый столбец — человек, по убыванию — {name}. Твой — акцентным цветом. Медиана {mitte}, наибольшее значение {min}{spitze} — {wer}.{unten}",
  "profil.nb.min": "не менее ",
  "profil.nb.unten": " Для одного значения запуск упёрся в предел страниц — показано ≥, и порядок вверху не окончательный.| Для {n} значений запуск упёрся в предел страниц — показано ≥, и порядок вверху не окончательный.| Для {n} значений запуск упёрся в предел страниц — показано ≥, и порядок вверху не окончательный.",
  "profil.nb.kopf3": "Сначала вопрос, потом расчёт: <b>что должно значить «охват»?</b> Возможны три ответа, и результаты у них разные. Каждый объясняется только <b>действиями</b> — тем, что человек делает до того, как что-либо вернётся. Никогда другими результатами: то, что у кого-то много сердечек и много подписчиков, ничего не объясняет — это одно и то же, посчитанное дважды.",
  "profil.nb.handlung.titelzahl": "число треков",
