  "profil.nb.ziel.wirkung": "Отдача на трек",
  "profil.nb.ziel.wirkung.was": "прослушиваний на трек — чего достигает отдельный трек",
  "profil.nb.ziel.dauer": "Выносливость",
  "profil.nb.ziel.dauer.was": "h-индекс — сколько треков держатся одновременно",
  "profil.nb.zu_wenige": "Для этого расчёта слишком мало чисел. Загрузи больше профилей кнопкой «Загрузить новые» на панели окружения или выбери другую цель.",
  "profil.nb.anteil": "<b>{name}</b> — {was}. Из общего разброса действия вместе объясняют <b>{gesamt}%</b>; самая большая отдельная доля — «{stark}», {starkp}%. Посчитано по {n} людям, все величины логарифмические.<br><span class=\"leise\">Доля усреднена по <b>всем</b> порядкам, в которых величины могли войти в модель (Линдеман, Меренда и Голд; та же идея, что и в разделении Шепли). Иначе первая взятая величина получила бы общую часть. — <b>Доля — не причина:</b> у человека с многими подписчиками может быть больше и ответных подписок; снимок не говорит, в какую сторону это идёт.</span>",
  "profil.nb.reg.weg": "Как возникает охват",
