  "profil.nb.ohne_profil": "{n} человек из списков лайкнувших пока без профиля — их загрузит следующее утреннее обновление.",
  "profil.nb.neue": "Загрузить новые",
  "profil.nb.neue.titel": "Загрузить профили тех, кто появился с прошлого раза — занимает секунды",
  "profil.nb.alles": "Обновить всё",
  "profil.nb.alles.titel": "Заново загрузить и уже имеющиеся показатели — около 20 минут и 800 запросов к Suno",
  "profil.nb.alles.frage": "Загрузить все показатели заново?\n\nЭто около 800 запросов к серверам Suno и примерно 20 минут. Процесс продолжится в фоне, даже если закрыть страницу.",
  "profil.nb.fertig": " — готово, новые показатели будут на месте при следующем открытии.",
