  "profil.nb.nicht_erklaert": "не объяснено",
  "profil.nb.info.kurz_h": "Коротко о причине",
  "profil.nb.info.kurz": "Твоё сообщество — <b>не случайная выборка</b>. Оно состоит из тех, кто тебя нашёл, а находят тебя в основном заметные люди.",
  "profil.nb.info.p1": "Это известный эффект — <i>парадокс дружбы</i>: <b>у твоих друзей в среднем больше друзей, чем у тебя.</b> Он выполняется почти всегда и почти для всех, и это не приговор, а следствие того, как складывается окружение: человек, подписанный на три тысячи людей, попадает в три тысячи окружений; подписанный на тридцать — в тридцать. Крупные оказываются представлены в твоём списке в сотни раз чаще.",
  "profil.nb.info.p2": "Скотт Фельд описал это в 1991 году; Эом и Джо показали в 2014 году, что это верно не только для числа связей, но почти для любой связанной величины — у учёных для цитирований, здесь для прослушиваний и сердечек.",
  "profil.nb.info.messbar_h": "Измеримо по твоим данным",
  "profil.nb.info.messbar": "Чем выше среднее над медианой, тем сильнее цифры определяются немногими крупными — и тем сильнее искажает эффект отбора:",
  "profil.nb.info.th.mitte": "Медиана",
