  "profil.nb.info.th.oben": "верхние 10% держат",
  "profil.nb.info.hirsch_h": "Почему h-индекс — самая честная величина",
  "profil.nb.info.hirsch": "Это самая малоискажённая величина. В этом и её сила: один трек-хит её не поднимает — для этого нужно много треков сразу. Поэтому эффект затрагивает её меньше всего. По прослушиваниям твой ранг был бы сильно искажён; по h-индексу — меньше всего.",
  "profil.nb.info.bilder_h": "Что это значит для картинок",
  "profil.nb.info.bilder_p1": "<b>«Я в нижней трети своего сообщества» верно почти для всех</b> — в том числе для тех, кто далеко выше среднего по всем пользователям. Ты систематически сравниваешь себя с самыми заметными.",
  "profil.nb.info.bilder_p2": "Чтобы измерить это чисто, нужна была бы случайная выборка всех пользователей Suno. Этот путь её не даёт: человека находишь, только если он где-то проявился — и ты снова попадаешь в тот же эффект.",
  "profil.nb.info.fuss": "Показатели выше посчитаны по {n} соседям, которые сами делают музыку. Они говорят о твоём окружении, а не о Suno в целом.",
  "profil.nb.info.fuss_unten": " Для {n} h-индексов запуск упёрся в предел страниц; это нижние границы, и они занижают медиану и среднее.",
