  "export.titel": "KlangTresor на внешнем диске",
  "export.erklaerung": "Замороженная копия всей коллекции записывается на переносной диск. Подключи его к нужному устройству, запусти скрипт — в браузере откроется KlangTresor со всеми треками: просто слушай, ничего не загружается и не сохраняется. Также создаётся папка <code>Musik/</code> с MP3, названными по трекам, и обложкой в заголовке файла — для телевизора, автомагнитолы и VLC. Следующие экспорты на тот же диск обновляют изменившееся.",
