  "studio.fx.megabass.was": "Bass+ сверху — вкл., выкл., и всё как прежде.",
  "studio.fx.tempo_hinweis": "Темп ≠ 100% — влияет также на индикаторы и тайминг караоке.",
  "studio.fx.lampen": "Лампы загораются, только когда их эффект действительно включается — исключение CLIP: он предупреждает, когда выход достигает полной шкалы (эквалайзер, ширина, реверберация и эхо складываются). Ширина стерео и темп — это <b>состояния, а не величины</b>: их ползунки не заполняются; середина — исходное положение. Темп никогда не запоминается — забытые 150% были бы загадкой. То, что действует лишь мимолётно (темп, соло, MEGA BASS, выключенная ступень, A/B), продолжает светиться на кнопке эквалайзера плеера после закрытия.",
