  "studio.eqmodus": "Эквалайзер: восемь фиксированных полос. Колокольная рама: те же фильтры, но свободные — шесть колоколов настраиваются по частоте, высоте и добротности Q (ширине полосы), два краевых фильтра поднимают или опускают всё ниже или выше своей частоты. Активен ровно один.",
  "studio.eq.glockenstuhl": "Колокольная рама",
  "studio.ref.knopf": "Взять играющий трек за образец",
  "studio.ref.titel": "Запоминает играющий трек как звуковой образец. Начальные значения «Как образцовый трек» затем подгоняют любой другой трек под его частотный профиль.",
  "studio.ref.weg": "Сбросить образец",
  "studio.deckel": "Без перегруза",
  "studio.deckel.titel": "Все полосы остаются ниже серого потолка трека — при включении, при перетаскивании и на начальных значениях. MEGA BASS лежит сверху и потолок игнорирует — для этого и нужна лампа CLIP",
  "studio.shift": "Сдвинуть всё: поднимает или опускает все полосы вместе",
  "studio.invers": "Инвертировать",
