  "studio.stapel.titel": "Отдельные колокола: каждый колокол фильтра сам по себе. Стопка колоколов: вклады складываются — подъёмы вверх, спады вниз, сумма образует внешний край",
  "studio.stapel.einzeln": "Отдельные колокола",
  "studio.stapel.stapel": "Стопка колоколов",
  "studio.mittel": "Усреднение показа",
  "studio.mittel.titel": "Насколько медленно серая область спектра следует за треком: скользящее среднее за заданное время. Коротко — быстро и дёргано, долго — спокойно и вяло.",
  "studio.ausgang.titel": "Что сейчас выходит из колонок — после эквалайзера, компрессора и эффектов",
  "studio.clip.titel": "Звук достигает полной шкалы и срезается. Убери что-нибудь — эквалайзер, ширина, реверберация и эхо складываются.",
  "studio.breite.titel": "Ширина стерео: 0% = моно (левый и правый одинаковы), 100% = как записано, 200% = разница между левым и правым удвоена",
  "studio.breite.vor": "перед компрессором",
  "studio.breite.vor.titel": "Два подхода: выкл = ширина после компрессора, как тембральный выбор после регулировки усиления — но тогда и после лимитера, который её уже не ловит. Вкл = ширина перед компрессором: он видит готовую стереокартину и удерживает даже удвоенные боковые каналы ниже полной шкалы (так делают при мастеринге, последний шаг в студии). Реверберация и эхо в обоих случаях берутся после компрессора.",
  "studio.hall.titel": "Реверберация большого зала, звучит ещё 2 с — никакой эквалайзер не может УБРАТЬ реверберацию",
