  "mess.dokument": "Измерить комнату — документ измерений",
  "mess.dokument.titel": "Весь ход измерений одним документом: тест тишины, проверка времени (сигнал), три вида шума и два свипа по два раза, две рампы громкости, рекомендации — все диаграммы сохраняются, в конце можно экспортировать.",
  "mess.wirkung": "Измерить, что делает звуковая студия",
  "mess.wirkung.titel": "Прежний пошаговый ход в панели: измеряет, что эквалайзер на самом деле делает в точке прослушивания (образец, настройки, серия уровней).",
  "mess.signal": "Чем измерять. Свип — тон, плавно идущий от низкого к высокому — обычный тестовый сигнал для комнат. Пока оценивается только то, насколько громко приходит каждая частота; прямой звук от реверберации здесь ещё не отделяется.",
