  "mess.mikro": "Что делает запись. Виртуальные устройства бесполезны: они не слышат комнату, а гоняют звук внутри компьютера.",
  "mess.abhoeren": "Послушать комнату",
  "mess.abhoeren.titel": "Без воспроизведения: непрерывно показывает, насколько громко в комнате и какие частоты мешают. Чтобы найти тихое место для микрофона.",
  "mess.rampe": "Пройти по уровням",
  "mess.rampe.titel": "Шагает по громкости и каждый раз измеряет. Показывает, растёт ли всё равномерно или с какого-то момента сдерживается.",
  "mess.abbrechen": "Отмена",
  "mess.abbrechen.titel": "Останавливает текущее измерение. Шум в комнате всё равно его испортил бы.",
  "mess.leeren": "Очистить серию",
  "mess.leeren.titel": "Удаляет собранные прогоны. Нейтральное опорное измерение остаётся.",
  "mess.neutral": "1 · Нейтрально",
  "mess.neutral.titel": "Первый прогон: звуковая студия обойдена. Без неё измерение показывает только цепочку колонка — комната — микрофон.",
  "mess.mit": "2 · С настройкой",
  "mess.mit.titel": "Второй прогон: с настройкой, действующей сейчас.",
  "mess.hg": "Показать или скрыть фон",
  "komp.modus": "Компрессор: классическая кривая с изломом (порог, соотношение, подъём, лимитер). Градационный компрессор: тихая/громкая точка (чёрная/белая точка у графика), гамма или сигмоида с одним регулятором — как в графической программе, но для звука. Активен ровно один; значения другого сохраняются.",
  "komp.kompressor": "Компрессор",
  "komp.gradation": "Градационный компрессор",
  "komp.aus": "Выкл",
  "komp.aus.titel": "Кривая выключена — линейно, ничего не выдумано",
  "komp.gamma": "Гамма",
  "komp.gamma.titel": "Гамма по оси дБ между тихой и громкой точкой: γ < 1 поднимает тихое и сжимает громкое (раскрывает тени) — внизу кривая становится крутой, затухания быстрее проваливаются в ничто; γ > 1 наоборот",
  "komp.sig": "Сигмоида",
  "komp.sig.titel": "Сигмоида: + делает середину контрастнее и сглаживает края (вверху как мягкий лимитер); − сжимает середину и делает края круче — тихое и громкое становятся жёстче",
  "komp.staerke": "Сила",
  "komp.staerke.titel": "Насколько сильно действует форма: гамма ¼ … 4, сигмоида −10 … +10",
  "komp.leise_laut": "Тихо / громко",
  "komp.leise_laut.titel": "Тихая точка (чёрная точка) · громкая точка (белая точка)",
  "komp.limiter": "Лимитер",
  "komp.limiter.titel": "Лимитер: порог −3 дБ, 20:1. Регулировка тогда удерживает пики (не среднее): пики ловятся мгновенно, громкость — с атакой 3 мс. Он смотрит на один блок вперёд и в качестве последней страховки жёстко срезает на верху кривой — страховочная сетка, а не тембр",
  "komp.gr.titel": "Изменение уровня — что компрессор сейчас убирает (−) или добавляет (+)",
  "komp.schwelle": "Порог",
  "komp.schwelle.titel": "Порог: начиная с этой входной громкости кривая изгибается — ниже него всё остаётся без изменений",
  "komp.verhaeltnis": "Соотношение",
  "komp.verhaeltnis.titel": "Соотношение: наклон выше порога — при 4:1 на 4 дБ больше на входе даёт 1 дБ больше на выходе",
  "komp.attack": "Атака",
  "komp.attack.titel": "Атака: как быстро компрессор хватает, когда становится громче — как автоэкспозиция привыкает к яркому свету (в режиме лимитера: пики мгновенно, громкость с атакой 3 мс)",
  "komp.release": "Восстановление",
  "komp.release.titel": "Восстановление: как быстро он отпускает, когда становится тише — автоэкспозиция снова привыкает к темноте",
  "komp.aufholen": "Подъём",
  "komp.aufholen.titel": "Подъём: возвращает громкость, которую забрал компрессор — поднимает всё на одну и ту же величину, вплоть до полной шкалы на 0 дБ; всё выше этого срезается.",
  "komp.diagonale": "Сбросить на диагональ",
  "komp.diagonale.titel": "Активный инструмент возвращается на диагональ — другой сохраняется",
  "kachel.video_eigen": "назначенная тобой анимированная обложка",
