  "sa.chart.karten": "Ключевые общие параметры, помогающие классифицировать трек.",
  "sa.chart.befunde": "Сверху — разделы из промпта текста песни; ниже — огибающая песни (громкость), удары (BPM) и блок-диаграммы проверенных находок для мест, где стереосигналы могут гасить друг друга и где уровень выше стандарта. Это ориентирует тебя перед подробным взглядом на отдельные измерения — линия воспроизведения (вертикальная белая линия) проходит через каждую дорожку, описывающую вещь во времени, так что каждое наблюдение привязано к месту в песне.",
