  "sa.tip.plays": "Общее число прослушиваний на Suno.",
  "sa.tip.likes": "Число лайков (голосов «за»).",
  "sa.tip.comments": "Число комментариев.",
  "sa.tip.ratio": "Прослушиваний на один лайк — чем меньше, тем чаще слушатели ставят лайк.",
  "sa.tip.age": "Возраст трека с момента публикации.",
  "sa.tip.ppd": "Среднее число прослушиваний в день с момента публикации.",
  "sa.tip.model": "Версия модели Suno, на которой был сгенерирован трек.",
  "sa.tip.dur": "Общая длительность трека.",
  "sa.tip.loud": "Средний уровень всего трека в децибелах ниже полной шкалы (0 дБ). Это чистое измеренное значение, а не слышимая громкость — по ней ориентируются Spotify и другие, она показана в «Насколько громко в целом?». Обычно: от −18 до −10 дБ.",
  "sa.tip.dyn": "Насколько самые громкие пики поднимаются над средним. Большой разрыв = живые удары, малый = плотно сжато. Обычно 6–16 дБ.",
  "sa.tip.key": "Основной тон из баса на «раз» Suno — там он почти всегда играет основной тон аккорда. Мажор или минор определяется по сосчитанной терции в мелодических голосах; если её нет (для пауэр-аккордов это правило), показан только основной тон.",
  "sa.tip.grenz": "До какого места доходят высокие и КАК они заканчиваются. Частота — это точка, начиная с которой высокие устойчиво примерно на 30 дБ тише средней области (1–8 кГц). Добавка говорит, обрезали ли их там: «резко» означает, что они обрываются круто (от 20 дБ на кГц) — такое оставляет формат файла вроде MP3 или сама модель; «мягко» означает, что они затухают естественно. Измерено 26.08.2026 на пяти WAV от Suno: при переходе с 17 на 21 кГц уровень упал на 8,5–19,6 дБ, то есть везде МЯГКО. У MP3 со скоростью 192 кбит/с в этом месте уровень падает больше чем на 40 дБ всего за один килогерц. При измерении по MP3 значение показывало бы край MP3, а не модели — поэтому с 26.08.2026 считается только по WAV.",
  "sa.tip.stereo": "Ширина стерео: насколько левый и правый различаются. Обычно 15–70 %.",
  "sa.tip.entropy": "Насколько равномерно энергия распределена по всем частотам (спектральная энтропия). Низкая = тональный/чистый, высокая = шумный/плотный.",
  "sa.tip.symmetry": "Как энергия развивается по ходу трека, по его кривой громкости в трёх частях: становится громче ↑, становится тише ↓, сначала громче, потом тише ∧, остаётся ровной ─.",
  "sa.tip.flux": "<b>Изменение звучания (спектральная флуктуация) — 8 полос</b><br>По горизонтали: время · 8 строк = 8 частотных полос (бас внизу, высокие вверху)<br>Яркость = насколько сильно эта полоса меняется от мгновения к мгновению, каждая полоса измеряется по своей шкале.<br><br>Яркая вспышка в басу = бас-бочка. Яркая вспышка в высоких = тарелки. Широкая вспышка по многим полосам = жёсткое вступление синтезатора. Всё тёмное = тянущийся звуковой ковёр без изменений. Мерцание в середине = мелодия с быстрыми нотами.",
  "sa.tip.spectro": "<b>Спектрограмма (время × частота)</b><br>По горизонтали: время · По вертикали: частота (20 Гц–22 кГц) с нотными линиями<br>Чёрный = нет сигнала. Белый = сильный. <span style=\"color:#f97306\">Оранжевый</span> = самые громкие десять процентов в этом месте.<br><br>Горизонтальные яркие линии = выдержанные звуки. Вертикальные штрихи = удары, ударные. Оранжевые области = преобладающие частоты. Каждое место измеряется относительно своего окружения, чтобы и тихие фрагменты были видны.",
  "sa.tip.stereospectro": "<b>Стереоспектрограмма — панорама по частотам</b><br>X: время · Y: частота · цвет: направление панорамы<br><span style=\"color:#ff6600\">■ Оранжевый</span> = преобладает левый канал. <span style=\"color:#1472eb\">■ Синий</span> = преобладает правый канал. Серый = по центру. Яркость = амплитуда.<br><br>Бас почти всегда серый = чистый микс. Высокие часто оранжевые/синие = реверберация, широко разлитая в пространстве. Полностью одноцветная частота = жёстко разведённый по краю инструмент.",
  "sa.tip.freq": "<b>Частотный спектр — live</b><br>По горизонтали: частота (20 Гц–20 кГц) · По вертикали: сила<br>Показывает, какие высоты тона звучат прямо сейчас. Бас слева, середина посередине, высокие справа.<br><br>Пики = преобладающие частоты. Ровная заливка = плотный звук. Идёт вместе с музыкой.",
