  "karte.les.kreuz.text": "прослушивания за последние 7 дней; длина = сколько их",
  "karte.les.farbe": "Цвет звезды = возраст",
  "karte.les.farbe.text": "самые старые красные, самые новые бело-голубые",
  "karte.les.schatten": "Тень = приватный",
  "karte.les.schatten.text": "есть, но без света — Suno его не показывает",
  "karte.les.flimmern": "Мерцание = новый",
  "karte.les.flimmern.text": "треки последних 7 дней мерцают",
  "karte.les.pulsieren": "Пульсация = гибрид",
  "karte.les.pulsieren.text": "куплет и припев звучат по-разному",
  "karte.les.doppel": "Двойная система = близнецы",
  "karte.les.doppel.text": "две версии одного трека в одной оболочке",
  "karte.les.faeden": "Нити = соседи",
  "karte.les.faeden.text": "под мышью: нити к шести ближайшим, прозрачность по близости",
  "karte.les.nebel": "Туманность = группа стиля",
