  "karte.les.sternbild": "Созвездие = классификатор",
  "karte.les.sternbild.text": "линии через его самые сильные треки",
  "karte.les.attraktor": "Аттрактор = центр масс",
  "karte.les.attraktor.text": "по одному на группу, струи = главная ось",
  "karte.les.bahn": "Траектория = маршрут",
  "karte.les.bahn.text": "путь, который корабль действительно пролетел",
