  "groupie.mass.beides": "Сердечки + комментарии",
  "groupie.mass.beides.text": "{n} сердечек и комментариев",
  "groupie.mass.beides.was": "Каждый человек размером со все сердечки и комментарии, которые он дал твоим трекам.",
  "groupie.mass.herzen": "Сердечки",
  "groupie.mass.herzen.text": "{n} сердечек",
  "groupie.mass.herzen.was": "Каждый человек размером с сердечки, которые он дал твоим трекам; кто только комментирует, того нет.",
  "groupie.mass.kommentare": "Комментарии",
  "groupie.mass.kommentare.text": "{n} комментариев",
  "groupie.mass.kommentare.was": "Каждый человек размером с его комментарии и ответы под твоими треками; кто только ставит сердечки, того нет.",
  "groupie.mass.zeichen": "Длина комментариев",
  "groupie.mass.zeichen.text": "{n} символов",
  "groupie.mass.zeichen.was": "Каждый человек размером со всё, что он написал у тебя, в символах; кто только ставит сердечки, того нет.",
  "groupie.mass.aktuell": "Актуальность",
  "groupie.mass.aktuell.text": "{n} (взвешено)",
  "groupie.mass.aktuell.was": "Сердечки и комментарии, более свежие весят больше: сегодняшние полностью, месячной давности вполовину, двухмесячной давности вчетверо меньше. Кто около четырёх месяцев ничего не давал, того нет.",
  "groupie.mass.titel": "Треки",
  "groupie.mass.titel.text": "{n} треков",
  "groupie.mass.titel.was": "Каждый человек размером с число твоих треков, которым он дал сердечко или комментарий.",
  "groupie.mass.treue": "Верность",
  "groupie.mass.treue.text": "{n} дней",
  "groupie.mass.treue.was": "Каждый человек размером со время от его первой до последней реакции, в днях; кто был только один раз, считается за один день.",
  "groupie.glied.art": "Вид реакции",
  "groupie.glied.art.was": "Разделение по тому, ставит ли человек только сердечки, только комментирует или делает и то и другое.",
  "groupie.glied.beziehung": "Отношение",
  "groupie.glied.beziehung.was": "Кто подписан на тебя и на кого подписан ты, по последнему состоянию списка наблюдателей.",
  "groupie.glied.ankunft": "Приход",
  "groupie.glied.ankunft.was": "Год первой реакции. Многие сердечки из списков Suno не содержат времени — кто дал только такие, находится под «Время неизвестно».",
  "groupie.glied.lebendig": "Активность",
  "groupie.glied.lebendig.was": "Была ли последняя реакция в последние четыре недели.",
  "groupie.glied.geschmack": "Вкус",
  "groupie.glied.geschmack.was": "Группа стиля звукового пространства, чьим трекам человек уделил больше всего внимания — относительно числа её треков. Цвета как в звуковом пространстве.",
  "groupie.areal.herzen": "только сердечки",
  "groupie.areal.beides": "сердечки и комментарии",
