  "mess.lauf.zu_leise": " — слишком тихо для надёжного замера: поднеси микрофон ближе к колонке или увеличь его уровень, затем повтори",
  "mess.lauf.ueberschreit": " — ВНИМАНИЕ: микрофон перегружен, запись доходит до полной шкалы; замер непригоден. Уменьши уровень микрофона или отодвинь его дальше, затем повтори",
