  "mess.dok.m.kulisse": "⚠ Фоновый шум изменился: разница до {db} дБ на {hz} Гц. Что-то добавилось (прибор, окно, разговор)?",
  "mess.dok.neu_pruefen": "Проверить снова",
  "mess.dok.m.trotzdem": "Всё равно измерить",
  "mess.dok.m.unveraendert": "Проверка тишины: фоновый шум не изменился",
  "mess.dok.m.groesste": " (наибольшая разница {db} дБ)",
  "mess.dok.m.laeuft": "<b>{name}</b> играет, {s} с — пожалуйста, молчи …",
  "mess.dok.m.fehl": "Замер не удался: {was}",
  "mess.dok.m.latenz_neu": "Время прохождения {ms} мс отличается от проверки времени ({v} мс) — повторяю автоматически.",
  "mess.dok.m.stille": "тишина",
  "mess.dok.m.eingang": "вход",
  "mess.dok.m.erster_terz": "прогон 1 (третьоктавы)",
  "mess.dok.m.gemessen_fein": "измерено · сверхточно",
  "mess.dok.m.erster": "прогон 1",
  "mess.dok.m.raumkurve": "кривая комнаты",
  "mess.dok.m.zweifel": " Ниже 150 Гц этот сигнал почти ничего не возбуждает — кривая комнаты там ненадёжна.",
  "mess.dok.m.abstand": "Запас над шумом <b>{db} дБ</b> в каждой полосе",
  "mess.dok.m.weit_weg": "(далеко от проверки времени — лучше повторить шаг)",
  "mess.dok.m.ueberschreit": "Микрофон перегружен — уменьши уровень микрофона и повтори шаг!",
  "mess.dok.m.unter20": "при запасе меньше 20 дБ над шумом кривая — скорее случайность, чем измерение: поднеси микрофон ближе или увеличь его уровень и повтори",
  "mess.dok.m.legende": " Сверху: сверхточная кривая замера, входной сигнал пунктиром, снизу точками тишина. Снизу: разница — <b>сама кривая комнаты</b>, залитая относительно нулевой линии.",
  "mess.dok.n.abstand": "запас над шумом {db} дБ",
  "mess.dok.r.titel": "КРИВАЯ ГРОМКОСТИ · {name}",
  "mess.dok.r.text": "Уровень приложения начинается с <b>выставленного уровня измерения ({p} %)</b> — ниже него замер был бы случайным — и растёт шагами по 3 дБ до 100 %, по три секунды {name} на шаг. После каждого шага пучок кривых растёт на одну линию; лестница ниже сопоставляет фактическое с ожидаемым. Подъём идёт, пока не будет измерен спад в басах <b>и подтверждён следующим шагом</b> — тогда отклик колонки известен, а громче только включится лимитер. Если ограничения не видно, подъём идёт до 100 %. Результат подаётся как <b>рекомендация</b>.",
  "mess.dok.r.laut": "⚠ Последний шаг — <b>на полную громкость</b>, это громко.",
  "mess.dok.r.vorher": "Перед этим, как всегда: проверка тишины.",
  "mess.dok.r.start": "Начать подъём",
  "mess.dok.r.kulisse": "⚠ Фоновый шум изменился ({db} дБ на {hz} Гц).",
  "mess.dok.r.trotzdem": "Всё равно начать",
