  "mess.dok.weiter": "Дальше",
  "mess.dok.r.stufe": "Шаг <b>{p} %</b> — {name}, 3 с …",
  "mess.dok.r.fehl": "Шаг {p} % не удался: {was}",
  "mess.dok.r.neu": "Подъём заново",
  "mess.dok.n.stufe": "шаг {p} %: {was}",
