  "mess.dok.r.hinter": "Лестница отстаёт <span class=\"dokwarn\">на {db} дБ от ожидаемого</span> — что-то по пути приглушает звук, хотя форма сохранилась.",
  "mess.dok.r.linear": "Линейно до 100 %: лестница следует ожидаемому (отклонение {db} дБ), а кривые комнаты лежат друг на друге.",
