  "mess.dok.z.konsens": "консенсус",
  "mess.dok.z.titel": "ИТОГ &amp; ПРОФИЛЬ",
  "mess.dok.z.steckbrief": "<b>Профиль системы</b><br>",
  "mess.dok.z.stille": "· Тишина в комнате: в среднем {was} — тест тишины выше показывает иголки с вероятными причинами<br>",
  "mess.dok.z.relativ": "{db} дБ (относительно)",
