  "mess.dok.z.guete0": "ещё не для измерения времени реверберации (нужно минимум 35 дБ) — поднеси микрофон ближе или увеличь его уровень",
  "mess.dok.z.guete_fein": " <span class=\"dokfein\">(действует выше примерно 100–200 Гц; ниже в жилых комнатах стоячие волны считаются по одной, а для реверберации не хватает ещё одного шага расчёта)</span>",
  "mess.dok.z.fehlt": "<b>Чего ещё не хватает по сравнению с современной практикой</b> (исследование от 28 авг.): шага расчёта, превращающего запись свипа в отклик комнаты на единичный хлопок — он дал бы время реверберации, чёткость, искажения по обертонам и отражения с их временем прохождения, из тех же записей, без нового тона.",
  "mess.dok.z.alle": "<b>Все кривые комнаты</b> — полностью нарисованы в <b>сопоставимом диапазоне {band}</b> (там минимум 60 % подходящих прогонов поднимаются на 20 дБ над своей тишиной); за его пределами бледно — там ничего не утверждается:",
  "mess.dok.z.band": "от {von} до {bis}",
  "mess.dok.z.streu": "Разброс между повторами (прогон 1 против 2, в диапазоне): ",
  "mess.dok.z.kreuz": "Наибольшая разница формы между методами (в диапазоне): ",
  "mess.dok.z.max": "<b>Максимальная громкость с исходным балансом</b> — изменение формы по шагам относительно первого:",
  "mess.dok.z.max100": "До 100 % басы держатся в пределах 4 дБ — в измеренном диапазоне уровней ограничения нет.",
  "mess.dok.z.maxp": "Форма сохраняется до <b>{p} %</b> — выше басы заваливаются.",
  "mess.dok.z.max_knopf": "Поставить уровень прослушивания на {p} %",
  "mess.dok.z.eq": "<b>Срез эквалайзером</b> — то, что выступает над консенсусом:",
  "mess.dok.z.eq_zeile": "{f}: +{ueber} дБ → регулятор {regler} на <b>{db} дБ</b>",
  "mess.dok.z.eq_anwenden": "Выставить на регуляторы",
  "mess.dok.z.eq_oeffnen": "Открыть эквалайзер",
  "mess.dok.z.eq_nichts": "<b>Срез эквалайзером:</b> в консенсусе ни одна полоса не выступает над соседними более чем на 3 дБ — исправлять нечего.",
  "mess.dok.z.komp": "<b>Компрессор</b> — два взгляда:",
  "mess.dok.z.komp_kette": "Что цепочка уже сжимает",
  "mess.dok.z.komp_hoer": "Что нужно для слышимости",
  "mess.dok.z.komp_nicht": "На пути к полной шкале цепочка берёт всего {db} дБ — она почти не сжимает. Студийному компрессору нечего компенсировать; то, что он делает, — это формирование звука, а не починка.",
  "mess.dok.z.komp_selbst": "До полной шкалы цепочка забирает {db} дБ — она сжимает сама. Рекомендация: сделай студийный компрессор мягче (соотношение в сторону 1:1), иначе сжатие будет двойным.",
  "mess.dok.z.komp_ohne_rampe": "Без подъёма о сжатии в цепочке ничего сказать нельзя.",
  "mess.dok.z.komp_raum": "Комната оставляет {db} дБ над шумом: пассажи, лежащие дальше ниже пика, тонут в фоновом шуме в точке прослушивания. Чтобы спасти тихие места, настрой компрессор так, чтобы они оставались выше этой линии — мягкое соотношение, порог на слух по самым тихим важным местам.",
  "mess.dok.z.komp_ohne_rausch": "Без прогонов шума ничего сказать нельзя.",
