  "mess.geleert": "Серия очищена — нейтральный эталонный замер остаётся.",
  "mess.reihe.start": "Пожалуйста, тишина — идут прогоны со свипом, около 20 секунд каждый. Громкость растёт шагами по четыре децибела от {von} %, максимум до {bis} %. Начинается тихо и останавливается, как только колонка начинает придерживать басы — так что громко становится, только если иначе нельзя. Больше ничего не меняется: тот же сигнал, та же длительность, то же место.",
  "mess.reihe.abgebrochen": "Серия прервана — предыдущие прогоны отброшены.",
  "mess.reihe.stufe": "Громкость {p} % — прогон {i} из {n} …",
  "mess.reihe.nichts": "на {p} % ничего не пришло — шаг пропущен, иду громче.",
  "mess.reihe.springt": "⚠ Время прохождения скачет: {ms} мс на этом шаге против {median} мс медианы серии — обнаружение прихода здесь ненадёжно, кривую этого шага читай осторожно.",
  "mess.reihe.gemessen": "Шаг {p} % измерен ({i} из {n}), запас над шумом {db} дБ",
