  "mess.reihe.still": ". Пожалуйста, не шуми.",
  "mess.reihe.gefunden": "Точка найдена: примерно с {p} % колонка начинает сама себя приглушать. Серия останавливается здесь — более громкий замер принёс бы только шум.",
  "mess.reihe.steht": "Серия громкости завершена: от {von} % до {bis} % ожидалось бы {erw} дБ, измерено {gem} дБ.",
  "mess.reihe.fiel": " При этом басы упали на {bass} дБ, а высокие на {hoehen} дБ относительно середины.",
  "mess.reihe.klirr": " Доля искажений на 40 Гц выросла с {a} % до {b} % — ",
  "mess.reihe.klirr_steigt": "она заметно растёт, значит, есть и искажения. Тогда нельзя с уверенностью сказать, на пределе колонка или микрофон.",
  "mess.reihe.klirr_gleich": "она практически не меняется. Значит, ничего не искажает; что-то убавляет уровень — а это может делать только колонка, у микрофона убавлять нечего.",
  "mess.reihe.kopfraum": " Микрофон остался на {db} дБ ниже полной шкалы.",
  "mess.reihe.neu_neutral": " Нейтральный эталонный замер теперь на {p} % — для серии настроек, пожалуйста, измерь «1 · Нейтрально» заново.",
  "mess.rb.saeulen": "Столбики: третьоктавные полосы   ·   белым: усреднено ({hz} Гц)",
