  "komp.mw.lautheit.titel": "насколько громким трек кажется на слух — со взвешиванием по слуху, так же как глаз воспринимает яркость, а не считает её экспонометром. Большинство стриминговых сервисов приводят её примерно к −14 (Apple −16): всё, что громче, там просто убавляют",
