  "ec.zone.effektraum": "Эффект-пространство",
  "ec.zone.besch.effektscheibe": "стекло перед объективом — туман, капли, царапины",
  "ec.zone.besch.effektraum": "пустое переднее пространство — дымка и частицы перед всем, что показывает картинка",
  "ec.wahl.tiefeVerdeckung.zone": "как в старом рецепте: зона вырезается мягко",
  "ec.text.stufe_szene": "Лежит в сцене <b>под</b> {namen} и движется вместе с камерой — если перетащить в конец цепочки, текст снова окажется на объективе поверх всего.",
  "ec.stufe.szene.titel": "Сцена — рисуется в диораме и движется вместе с ней: когда камера приближается, этот эффект становится крупнее.",
  "ec.stufe.kamera.titel": "Камера — это сам кадр: сдвиг, зум, наклон, резкость.",
  "ec.stufe.film.titel": "Плёнка — сидит на камере и остаётся на месте: камера, которая приближается, не приближает собственное зерно плёнки.",
  "ec.stufe.szene": "Сцена",
