  "ec.stufe.hinweis": "Рисование идёт не сверху вниз, а по шагам: сначала сцена, затем камера, в конце плёнка. Здесь это значит: {namen}. Поэтому перенос карточки между двумя шагами картинку не меняет — внутри своего шага меняет.",
  "ec.kette.leer.vorb": "Чтобы настроить источник до включения визуальных эффектов, можно {link}.",
  "ec.kette.leer.vorb_link": "открыть панель подготовки",
  "ec.kette.leer.beispiel": "Чтобы применить эффект, открой «Добавить эффект» и выбери один — для первого впечатления от пульсирующей яркости просто нажми {link}.",
  "ec.kette.leer.beispiel_link": "здесь",
