  "ec.karte.zuklappen": "свернуть",
  "ec.karte.kein_medium": "В цепочке <b>нет среды</b> — без неё видно только то, что луч <i>освещает</i>, а не сам луч. <b>Плёночная дымка</b> делает его видимым; она подхватывает свет, где бы ни стояла в цепочке.",
  "ec.karte.keine_leuchte": "В цепочке нет источника света — без него дымка показывает лишь то, что даль теряет контраст. Прожектор, лазер, световые лучи, огонь, пламя, каустика, светящиеся частицы или строб делают её видимой.",
  "ec.teilchen.quelle": "Источник",
  "ec.raum.ort_x": "Положение X",
  "ec.raum.ort_y": "Положение Y",
  "ec.raum.drehung": "Поворот (°)",
  "ec.teilchen.ausblenden": "Затухание",
