  "ec.raum.ursprung": "Исходная точка",
  "ec.raum.im_bild": "внутри картинки",
  "ec.raum.ausserhalb": "за пределами картинки",
  "ec.raum.winkel": "Угол",
  "ec.teilchen.ausdehnung": "Протяжённость",
  "ec.teilchen.ausdehnung_x": "Протяжённость X",
  "ec.teilchen.ausdehnung_y": "Протяжённость Y",
  "ec.teilchen.kanone.punkt": "Пушка стреляет из одной точки — даже без выбранного источника. Здесь точка — это положение; линия или круг поверх превращают её в несколько стволов.",
  "ec.teilchen.schnuppe.quelle": "Падающая звезда приходит из ОДНОЙ точки. Без выбранного источника она стартует за краем картинки и прочерчивает её; источник делает это место её радиантом.",
  "ec.teilchen.schar.quelle": "Стая кружит вокруг блуждающего центра. Выбранный источник закрепляет этот центр — тогда она кружит вокруг места, а не движется дальше.",
  "ec.teilchen.ueberall": "Частицы появляются везде и дрейфуют. Давление, расхождение веером и длину открывает только источник.",
  "ec.teilchen.flug": "Полёт",
  "ec.teilchen.auftrieb": "Подъём",
  "ec.teilchen.schnuppe.auftrieb": "Здесь подъём наклоняет траекторию: −1 — крутое падение, 0 — ровный ход, +1 — набор высоты. Темп делает падающую звезду быстрой, ветер её скашивает, затухание говорит, как долго светится хвост.",
  "ec.teilchen.schar.auftrieb": "Здесь подъём говорит, как высоко висит стая. Темп — её скорость и взмахи крыльев, ветер отклоняет её путь в сторону.",
  "ec.teilchen.schnuppe.still": "Этот вид игнорирует давление, направление, расхождение веером и длину — падающая звезда следует своей прямой траектории.",
  "ec.teilchen.schar.still": "Этот вид игнорирует давление, направление, расхождение веером, длину и затухание — стая следует своим правилам.",
  "ec.teilchen.kanone.salven": "Залпы следуют приводу справа: фиксированная частота или сетка тактов. Без привода она спокойно стреляет каждые 1,6 с.",
  "ec.teilchen.vorschau.titel": "Источник и двенадцать траекторий в миниатюре: где частицы появляются, куда летят, где затухают",
  "ec.raum.titel": "Пространство",
