  "ec.schleife.art.pixel": "Пиксели",
  "ec.schleife.prinzip.keiner": "всё видео растягивается на весь клип, в конце клипа оно прыгает в начало",
  "ec.schleife.prinzip.ruecklauf": "видео идёт вперёд, а в переходе быстро возвращается к началу — размытие меньше 8 %",
  "ec.schleife.prinzip.pendel": "туда и обратно по отрезку в реальном темпе, в точках разворота мягко — переход не нужен",
