  "ec.schleife.prinzip.unschaerfe": "в середине перехода, скрытый размытием, конец меняется на начало",
  "ec.schleife.prinzip.blende": "последний кадр плавно переходит в первый",
  "ec.schleife.prinzip.kreuzzoom": "зум с размытием скрывает подмену в середине",
  "ec.schleife.prinzip.wisch": "начало выталкивает конец влево",
  "ec.schleife.prinzip.schwarz": "затемнение до чёрного, там подмена, затем снова светлеет",
  "ec.schleife.prinzip.weiss": "осветление до белого, там подмена, затем обратно",
  "ec.schleife.prinzip.blitz": "резкая подмена под короткой белой вспышкой — для графики; для снятого на камеру материала грубовато",
