  "ec.text.ort_vorgabe": "Положение текста сброшено к значению по умолчанию.",
  "ec.kb.geloest.eins": "Целевая точка снята — остаётся {n}.",
  "ec.kb.geloest.mehr": "Целевая точка снята — остаются {n}.",
  "ec.kb.geloest.letzter": "Последняя целевая точка снята — камера теперь показывает картинку целиком.",
  "ec.brand.anteil": "Выгорело: {p} % картинки",
  "ec.brand.quelle": " (сам источник: {p} %)",
  "ec.brand.titel": "Столько пикселей недавно были на пределе хотя бы в одном цветовом канале (пик за последние две секунды). Начиная отсюда, большая сила не делает картинку ярче, а лишь увеличивает выгоревшую область.",
  "ec.kb.px_grenze": "Путь заканчивается на {max} %, и это расчёт: по наибольшему скачку близости на пиксель (медиана {sprung} по 325 картам глубины коллекции) разрыв в {sicht} пикселей — ширина, начиная с которой продолжение края заведомо не выдерживает, — был бы достигнут при {grenze} %.",
  "ec.kb.px_aus": "Выкл.: картинка равномерно увеличивается — это увеличенное фото, а не движущаяся камера. ",
  "ec.kb.px_satz": "Ближнее опережает дальнее на {s} % длинной стороны картинки — в размере студии {px} пикселей — и именно там, где кадр сместился дальше всего; к середине движения это уменьшается, потому что смещение расходится лучами из точки, к которой оно направлено. При этой настройке самый резкий край глубины в картинке разрывается на {riss} пикселей, у каждого десятого трека — на {riss90}; измерено по всем 325 картам глубины в размере студии при самом тесном кадре. Разрыв заполняется из дальнего слоя. ",
  "ec.kb.lupe.anderthalb": "в полтора раза",
  "ec.kb.lupe.fach": "{f}×",
  "ec.kb.lupe.teil": "точка {n} (теснота {z}) {wort}",
  "ec.kb.lupe.satz": "Выход — {W} × {H} пикселей, источник — {bw} × {bh}; до тесноты {eins} ничего не увеличивается. Увеличено: {teile}.",
  "ec.kb.liste_und": " и ",
  "ec.kb.neu.voll": "Пять целевых точек — это предел",
  "ec.kb.neu.titel": "Ставит точку на свободное место — то же, что щелчок по свободной области сцены",
