  "ec.kb.liste.ort": "Положение и теснота",
  "ec.kb.liste.fokus": "Фокус по прибытии",
  "ec.kb.liste.enge": "теснота {z}",
  "ec.kb.ps.keiner": "Целевых точек нет — камера стоит на картинке целиком. ",
  "ec.kb.ps.ohneplan_1": "{n} целевая точка: {z} переездов, плюс {n} остановка на точке и одна на картинке целиком. ",
  "ec.kb.ps.ohneplan_n": "{n} целевых точек: {z} переездов, плюс {n} остановок на точках и одна на картинке целиком. ",
  "ec.kb.ps.zuege_1": "{n} целевая точка: {z} переездов по {f} с. ",
  "ec.kb.ps.zuege_n": "{n} целевых точек: {z} переездов по {f} с. ",
  "ec.kb.ps.halt_1": "Камера стоит на точке {h} с — все остановки одинаковой длины — и на картинке целиком {ha} с. ",
  "ec.kb.ps.halt_n": "Камера стоит на каждой точке {h} с — все остановки одинаковой длины — и на картинке целиком {ha} с. ",
  "ec.kb.ps.nur_beruehrt": "На точки не остаётся ни одного целого удара — их лишь касаются; на месте стоит только картинка целиком, {ha} с. ",
  "ec.kb.ps.kein_halt": "Переезды заполняют весь клип — остановок не остаётся, даже на картинке целиком. ",
  "ec.kb.ps.passt_offen": "Сколько точек поместится в длину клипа, станет известно, когда у трека появится длина.",
  "ec.kb.ps.passt_0": "В эту длину клипа при таком темпе не помещается ни одной точки",
