  "ec.ablage.fehlt_n": "Эффектов, которых эта версия больше не знает, и они пропущены: {n}",
  "ec.ablage.nicht_gesichert": "ещё не сохранено. «Сохранить для этого трека» сохранит; закрыть и открыть снова — вернуть сохранённый рецепт.",
  "ec.ablage.leer_altes_rezept": "здесь теперь ничего нет — у трека по-прежнему лежит старый рецепт. «Удалить» уберёт его, закрыть и открыть снова — вернуть его.",
  "ec.ablage.leer_nichts": "здесь теперь ничего нет — и у трека тоже ничего не лежит.",
  "ec.vorb.reg.kurve": "Кривая",
  "ec.vorb.reg.feinheiten": "Тонкая настройка",
  "ec.vorb.reg.tiefe": "Глубина",
  "ec.vorb.auto_titel": "Чёрная и белая точки по гистограмме (0,5 % / 99,5 %)",
  "ec.vorb.auto": "Авто-уровни",
  "ec.vorb.zuruecksetzen_titel": "Сбросить все корректировки подготовки к нейтральным — «Удалить» внизу, наоборот, касается сохранённого эффект-клипа",
  "ec.vorb.zuruecksetzen": "Сбросить",
  "ec.vorb.tonwert": "Тон",
  "ec.vorb.marken": "Тяни метки внизу, чтобы задать чёрную и белую точки",
  "ec.vorb.raum": "Пространство",
  "ec.vorb.raumtiefe": "Глубина пространства",
  "ec.vorb.raumtiefe_satz": "Глубина пространства, определённая с помощью ИИ, говорит лишь о <i>порядке</i> объектов спереди назад. Измерять расстояния нельзя. Поэтому глубину нужно задавать в ширинах картинки — портрет имеет глубину около 0,2 ширины картинки, пейзаж — 3 и больше. Чаще всего это зависит от картинки.",
  "ec.vorb.zonen": "Зоны",
  "ec.vorb.zonen_satz": "На карте глубины, полученной с помощью ИИ из обложки, гистограммой глубины у правого края картинки можно задать зоны для эффектов — как на театральной декорации. Просто сдвигай заранее выбранные границы, ставь новые <b>одним щелчком</b> или убирай их <b>двойным щелчком</b>. Для лучшей ориентации поворачивай рельеф мышью; двойной щелчок снова выравнивает его.",
  "ec.vorb.raumfolge": "Пространство спереди назад",
  "ec.vorb.anteil_tiefe": "{p} % глубины",
  "ec.vorb.raumfuss": "Всё это лежит <b>перед линзой</b> и движется вместе с камерой. Зерно и виньетка возникают только за ней, в плёнке и в объективе — они приклеены к картинке и не масштабируются.",
  "ec.vorb.keine_karte": "У этой картинки нет карты глубины — без неё зон не бывает.",
  "ec.vorb.eine_zone": "Сейчас задана <b>всего одна зона</b>: значения глубины этой картинки образуют лишь одно скопление, поэтому нет впадины, по которой можно было бы разделить две плоскости. Границу всё равно можно поставить вручную.",
  "ec.vorb.n_zonen": "Сейчас задано зон: <b>{n}</b>",
  "ec.vorb.zone_name": "глубины картинки — <b>{name}</b>",
  "ec.vorb.max_grenzen": "Максимум — {n} границ: больше плоскостей зритель уже не различит.",
