  "ec.rezept.bildzeile_alt_n": "У эффектов ({n}) было «Глубина по строке изображения»; ползунок убран, значение больше ни на что не влияет",
  "ec.rezept.fahrt_alt_eins": "один эффект был старым «Движением»; оно убрано и удалено — эффект Кена Бёрнса умеет всё, что умело оно",
  "ec.rezept.fahrt_alt_n": "Эффектов, которые были старым «Движением»: {n}; оно убрано и удалено — эффект Кена Бёрнса умеет всё, что умело оно",
