  "ec.sperre.fuss": "Во время вывода нижняя панель не принимает решений — работает только «Отмена». Потом кнопка снова появится.",
  "ec.sperre.pult": "Во время вывода источник, подготовка, цепочка эффектов и повтор стоят на месте: изменение посреди прогона сменило бы картинку в готовом видео. Нижняя панель тоже до конца не принимает решений — работает только «Отмена». Остальное приложение продолжает работать — плеер, альбом и другие экраны остаются доступны.",
