  "ec.voll.kein_kodierer": "В этом браузере нет кодировщика кадров (WebCodecs). Целую песню можно было бы снять только в реальном времени — при этом метки времени уплывают, и картинка расходится с музыкой. Поэтому здесь ничего не выводится.",
