  "ec.stufe.loop": "Эффект-клип как повтор",
  "ec.stufe.quelle.erklaer": "Здесь можно выбрать картинки или видео для эффект-клипа.",
  "ec.stufe.vorb.erklaer": "При необходимости здесь можно оптимизировать вид источника и информацию о его глубине. <b>Кривая</b> позволяет оптимизировать общую тональную кривую или кривую по каналам. С помощью <b>Тонкой настройки</b> можно улучшить экспозицию, контраст, света, тени, цвет, резкость и многое другое. Сами данные обрабатываются напрямую, но меняются только в просмотре. <b>Глубина</b> задаёт, как картинки должны восприниматься как пространство; некоторым эффектам нужно назначение зон, в которых они должны действовать.",
  "ec.stufe.kette.erklaer1": "Каждый эффект накладывает слой на выбранный источник. Они действуют сверху вниз. Каждый слой накладывает эффект поверх всех заданных ранее.",
  "ec.stufe.kette.erklaer2": "Пульсы бьются в такт песне.",
  "ec.stufe.kette.erklaer3": "Значок соло показывает один эффект отдельно.",
  "ec.stufe.kette.erklaer4": "Сочетание эффекта и источника образует эффект-клип.",
  "ec.stufe.loop.erklaer1": "Suno воспроизводит видео к песне в бесконечном цикле и разрешает не больше 10 секунд. Чтобы пульсы оставались в такт на протяжении всей песни, клип собирается синхронно с целым числом ударов такта. Программа подбирает длину так, чтобы клип как можно дольше шёл синхронно с музыкой.",
  "ec.stufe.loop.erklaer2": "В конце клипа картинка должна точно вернуться к началу: эффекты делают это автоматически, без рывков и швов. Видео соответственно обрезаются (скорость) и, если начало и конец различаются, получают переход.",
  "ec.studio.titel": "Студия эффект-клипов",
  "ec.studio.spielen_titel": "Запустить трек в плеере — тогда пульсом управляет настоящая песня",
  "ec.studio.spielen": "▶ Воспроизвести трек",
