  "ec.loop.ansicht_titel": "Предпросмотр показывает картинку из выведенного клипа, которую Suno показывает в то же время песни. Включается, когда открывается этот шаг, и выключается, когда открывается другой.",
  "ec.loop.ansicht": "показать как клип 10 с",
  "ec.loop.schlaege_im_clip": "Ударов в клипе",
  "ec.loop.weniger_titel": "меньше ударов — клип короче, видео идёт быстрее",
  "ec.loop.mehr_titel": "больше ударов — клип длиннее (не больше 10 с), видео идёт спокойнее",
  "ec.loop.selbst_schlaege_titel": "пусть сама выберет число ударов, которое лучше всего держится в такт на протяжении всей песни",
  "ec.loop.von_selbst": "автоматически",
  "ec.loop.uebergang_enden": "Переход на концах петли",
  "ec.loop.kuerzer_titel": "короче — в половинах долей; клип остаётся той же длины, видео получает время",
