  "ec.loop.yachse_titel": "шкала времени видеоматериала, снизу вверх",
  "ec.loop.yachse_name": "Видео",
  "ec.loop.leiste_titel": "По горизонтали — версия, зацикленная KlangTresor, по вертикали — время в видеоматериале: кривая показывает, какой кадр видео идёт в какой момент клипа, заливка — переход, чёрточки внизу — доли",
