  "ec.loop.xachse_name": "зацикленный клип",
  "ec.loop.kosten": "при первом включении видео один раз измеряется (несколько секунд); с видео «Вывести 10 с» длится дольше",
  "ec.fuss.effektclip": "Эффект-клип",
  "ec.fuss.sichern_titel": "Сохранить источник, подготовку, цепочку эффектов и петлю в треке — плитка и сцена затем рисуют это вживую, в такт песне",
  "ec.fuss.sichern": "Сохранить для этого трека",
  "ec.fuss.ungesichert_titel": "В студии есть то, чего нет в треке в таком виде — «Сохранить для этого трека» сохранит это, а если закрыть и открыть снова, вернётся сохранённый рецепт",
  "ec.fuss.ungesichert": "ещё не сохранено",
  "ec.fuss.loeschen_titel": "Удалить эффект-клип, сохранённый в треке (источник, подготовку, цепочку эффектов и петлю) — плитка и сцена снова покажут неподвижную картинку. Удаляется только сохранённый рецепт: обложка и видео остаются, а то, что настроено здесь в студии, остаётся и его можно снова сохранить.",
  "ec.fuss.loeschen": "Удалить",
  "ec.fuss.kopieren_titel": "Запомнить текущее состояние студии, чтобы перенести его на другой трек",
  "ec.fuss.kopieren": "Копировать",
  "ec.fuss.einfuegen_titel": "Применить запомненный рецепт к этому треку — при этом ничего не сохраняется",
  "ec.fuss.einfuegen": "Вставить",
  "ec.fuss.video_titel": "До десяти секунд в MP4 в папку загрузок — достаточно долго, чтобы клип держал такт на протяжении всей песни, без звука, в формате источника, с фирменным знаком",
  "ec.fuss.video": "Вывести 10 с",
  "ec.fuss.voll_titel": "Вся песня в MP4 в папку загрузок: та же картинка, что на плитке, на всю длину, в формате источника, с фирменным знаком. Всё это время студия стоит неподвижно.",
  "ec.voll.ton_titel_kurz": "audio.mp3 трека попадёт в видео как звуковая дорожка",
  "ec.voll.abbrechen_titel": "Прервать запуск — недостроенное видео будет удалено в приложении, ничего не останется",
  "ec.voll.abbrechen": "Отмена",
  "ec.fuss.hilfe": "Сохраняются источник, подготовка, цепочка эффектов и петля. Если трек играет в плеере, пульсы бьются в настоящий такт. Клавиши: <kbd>←</kbd><kbd>→</kbd> источник · удерживать <kbd>V</kbd>: без эффектов (в подготовке) · <kbd>Esc</kbd> закрыть",
  "ec.kette.hinzufuegen": "Добавить эффект …",
