  "ec.rezept.quelle_fehlt": "его источник отсутствует, показана обложка",
  "ec.rezept.geladen": "Эффект-клип трека загружен",
  "ec.rezept.keiner": "у трека ещё нет эффект-клипа",
  "ec.tiefe.boden_trennt_nicht": "Эта карта глубины ничего не разделяет (разброс {s} из 255) — на ней нет поверхности земли, из которой что-то могло бы подниматься.",
  "ec.tiefe.boden_ohne_raum": "На этой карте есть поверхность земли ({n} ячеек сетки), но над её ячейками нет выбранной области пребывания — для частицы там нет места.",
  "ec.tiefe.boden_keiner": "На этой карте ни одна точка не удаляется к верху — на ней нет поверхности, похожей на землю.",
  "ec.titel.abgang_instrumental": "Этот трек инструментальный: название уходит через четыре такта.",
  "ec.titel.abgang_bei": "Здесь уход заканчивается на {t} с, до первой строки.",
  "ec.titel.abgang_ohne_lyrik": "Без очищенного текста песни оно уходит через четыре такта.",
  "ec.titel.auftritt_partikel": "Только в целом треке: название собирается за два такта из частиц того вида, что в цепочке, стоит и растворяется за два такта по направлению ветра — вид, цвет, размер, ветер и тяжесть берутся из эффекта частиц. {hier}",
  "ec.titel.auftritt": "Только в целом треке: один удар на появление, пауза, уход за один удар до первой вокальной строки (не раньше чем через два такта). Появление плавно замедляется, уход плавно ускоряется — регулятора для этого нет. {hier}",
  "ec.titel.zehnsekuender": "В десятисекундном клипе название неподвижно — появление и уход работают только в целом треке.",
  "ec.titel.partikel_fehlt": "Для «Из частиц» нужен эффект частиц в цепочке — пепел, пыль, искры, блёстки, снег, пух одуванчика или светлячки. А пока название стоит неподвижно.",
  "ec.titel.hochformat": "Вертикальный формат: Reels, TikTok и Shorts накладывают элементы управления примерно на нижнюю пятую часть картинки — до положения Y 0,78 текст остаётся свободным.",
  "ec.titel.im_karaoke_band": "Название стоит в полосе караоке — сдвиг положения Y вверх (примерно до 0,12) поднимает его над ней.",
  "ec.lyrik.deckung_gering": "Whisper нашёл только {p} % слов — слишком мало для надёжных меток времени",
  "ec.lyrik.japanisch": "Текст японским письмом — Whisper пишет транскрипцию, сопоставление невозможно",
  "ec.lyrik.zurueckgestellt": "очищенный текст песни отложен",
  "ec.lyrik.nie_gerechnet": "для этого трека очищенный текст песни не рассчитан — он создаётся в утреннем обновлении в шаге «Опорные точки времени для караоке через Whisper» (Whisper должен быть настроен, см. START-HIER.md); у чужих треков его нет",
  "ec.lyrik.laden_fehler": "очищенный текст песни не удалось загрузить — через 30 с будет ещё одна попытка",
  "ec.lyrik.kein_gesang": "<b>Нечего рисовать</b> — в этом треке нет вокала.",
  "ec.lyrik.deckung": "Whisper нашёл {p} % слов",
  "ec.lyrik.geschaetzt_1": "{n} строка с оценочным временем",
  "ec.lyrik.geschaetzt_n": "Строк с оценочным временем: {n}",
  "ec.lyrik.gestrichen_1": "{n} строка не спета, пропущена",
  "ec.lyrik.gestrichen_n": "Строк не спето и пропущено: {n}",
  "ec.lyrik.zeitanker": "Опорные точки времени из утреннего обновления: {teile}.",
  "ec.lyrik.wird_geladen": "Очищенный текст песни этого трека сейчас загружается.",
  "ec.lyrik.keine_zeile": "<b>Нечего рисовать</b> — {grund}.",
  "ec.lyrik.keine_fuer_titel": "для этого трека нет очищенного текста песни",
  "ec.lyrik.loop_weg": "В виде петли и в десятисекундном клипе строка пропускается — она относится к целому треку.",
  "ec.lyrik.freie_uhr": "Плеер остановлен — строки идут по свободным часам. Запусти трек, и строка встанет в такт пению.",
  "ec.tiefe.geliehen": "Карта глубины этого источника <b>позаимствована у обложки</b> — анимация Suno создана на её основе, геометрия остаётся примерно той же. Где видео отличается от неё, отличается и глубина.",
  "ton.hinweis.kopf": "Твои треки ({n}) на месте — звука пока нет.",
  "ton.hinweis.text": "Картинки, тексты и цифры KlangTresor загрузил. Аудиофайлы Suno с 03.09.2026 больше не выдаёт по ссылкам. Есть два пути, чтобы получить их, и первый ничего не стоит.",
  "ton.weg1": "1 · То, что у тебя уже есть.",
  "ton.weg1.frage": "Ты раньше скачивал свои песни с Suno?",
  "ton.weg1.selbst": "Я сам посмотрю в твоих <b>папках загрузок и музыки</b>. Если они лежат где-то ещё, укажи папку",
  "ton.weg1.waehle": "Выбери папку, в которой они лежат",
  "ton.weg1.erkenne": "я узнаю файлы Suno по содержимому, даже переименованные и в подпапках, и сопоставляю их с твоими треками. Остальную твою музыку я не трогаю, ничего не перемещается и не удаляется.",
  "ton.ordner_waehlen": "Выбрать папку …",
