  "studio.songeq.und": " и ",
  "studio.songeq.an": "Этот трек играет со своим {teile}. Щелчок отключает особые изменения звука для отдельных треков — везде, до следующего щелчка.",
  "studio.songeq.aus": "У этого трека был бы свой {teile}, но особые изменения звука для отдельных треков отключены. Щелчок включает их снова.",
  "studio.kerbe.fremd": "чужой трек — сканирования нет (в виде файлов есть только твои собственные треки)",
  "studio.kerbe.eingefroren": "Замороженная копия — здесь сканирование не выполняется; новые результаты приходят с новым экспортом с компьютера, на котором работает KlangTresor",
